//! Quality snapshot for denoise, generated by sdsp-test-kit.
//!
//! Fixed probes through the real CLAP plugin, recorded to `tests/quality.snap`.
//! A change in any of these numbers is a change in how the plugin sounds, and
//! the test fails until the snapshot is re-recorded on purpose:
//!
//!     SDSP_UPDATE_SNAPSHOTS=1 cargo test -p superduper-denoise --test quality

use sdsp_test_kit::probes::{self, db};
use sdsp_test_kit::{render_effect, PluginUnderTest, Suite};

struct Target;
impl PluginUnderTest for Target {
    type Plugin = superduper_denoise::SuperDuperDenoise;
    const ID: &'static std::ffi::CStr = c"co.superduperai.denoise";
}

const SR: f64 = 48_000.0;

#[test]
fn quality_snapshot() {
    // Wider than the default: several plugins have noise sources or LFOs that
    // do not restart identically, and a snapshot that flaps teaches people to
    // ignore it.
    let mut s = Suite::new("denoise", concat!(env!("CARGO_MANIFEST_DIR"), "/tests/quality.snap"))
        .default_tolerance(1.0);
    let frames = 1 << 15;

    let tone = probes::tone(SR as f32, 1000.0, 0.5, frames);
    let (out, _) = render_effect::<Target>(SR, &tone, &tone);
    s.record("tone_gain_db", probes::gain_db(&tone, &out));
    s.record("tone_peak_db", db(probes::peak(&out)));
    s.record("tone_thd_db", probes::thd_at(&out, 1000.0, SR as f32));
    for (band, level) in probes::band_shape(&out, SR as f32) {
        s.record(format!("tone_band_{band}"), level);
    }

    let noise = probes::noise(frames, 0.3);
    let (nout, _) = render_effect::<Target>(SR, &noise, &noise);
    s.record("noise_gain_db", probes::gain_db(&noise, &nout));
    s.record("noise_max_step", probes::max_step(&nout));
    for (band, level) in probes::band_shape(&nout, SR as f32) {
        s.record(format!("noise_band_{band}"), level);
    }

    // An impulse shows the tail: reverbs, delays and filters all differ here,
    // and a dead tail is the classic "plugin silently stopped working".
    let imp = probes::impulse(frames);
    let (iout, _) = render_effect::<Target>(SR, &imp, &imp);
    s.record("impulse_rms_db", db(probes::rms(&iout)));
    s.record("impulse_peak_db", db(probes::peak(&iout)));

    sdsp_test_kit::params::record_table(&mut s, superduper_denoise::PARAMS);
    s.finish();
}

#[test]
fn parameter_table_is_consistent() {
    // Ids dense and ordered, defaults inside range, names unique, stepped
    // params actually discrete. The table is hand-maintained and its indices
    // are duplicated into P_* constants, presets and the GUI.
    sdsp_test_kit::params::check_table("superduper-denoise", superduper_denoise::PARAMS, &[]);
}

#[global_allocator]
static ALLOC: sdsp_test_kit::alloc::CountingAllocator = sdsp_test_kit::alloc::CountingAllocator;

#[test]
fn process_does_not_allocate() {
    // The real version of sdk/tests/rt_safety.rs: that one reads the text of
    // process(), this one counts every malloc inside it, helpers included —
    // which is where the ones found in review actually lived.
    let frames = 1 << 14;
    let noise = probes::noise(frames, 0.3);
    sdsp_test_kit::alloc::reset();
    let _ = render_effect::<Target>(SR, &noise, &noise);
    sdsp_test_kit::alloc::assert_rt_clean("superduper-denoise", frames / 512);
}

/// Through the real CLAP host with default params (Spectral, adaptive, −12 dB): steady white
/// noise is the floor itself, so after the ~1.5 s minimum-statistics window it must be pulled
/// down by close to the full reduction.
#[test]
fn default_spectral_pulls_steady_noise_down() {
    let frames = SR as usize * 4;
    let noise = probes::noise(frames, 0.1);
    let (out, _) = render_effect::<Target>(SR, &noise, &noise);
    let tail = frames / 2..frames;
    let change = db(probes::rms(&out[tail.clone()])) - db(probes::rms(&noise[tail]));
    eprintln!("steady noise through the plugin: {change:.1} dB");
    assert!(change < -8.0, "noise only changed {change:.1} dB");
}

/// The learned Spectral profile is part of the session: save, load into a fresh instance,
/// and the profile comes back both for the next save and queued for the audio thread.
#[test]
fn learned_profile_is_saved_in_plugin_state() {
    use std::sync::atomic::Ordering;
    use superduper_denoise::{PluginShared, SavedProfile, P_REDUCTION};
    let a = PluginShared::new();
    let bins: Vec<Vec<f32>> = (0..2).map(|c| (0..1025).map(|k| (k + c) as f32 * 1e-6).collect()).collect();
    *a.saved_profile.lock() = Some(SavedProfile { sample_rate: 48_000.0, bins: bins.clone() });
    a.params[P_REDUCTION].store(21.0, Ordering::Relaxed);
    let json = a.save_state_json();
    eprintln!("state with profile: {} bytes", json.len());
    let b = PluginShared::new();
    b.load_state_json(&json).expect("load");
    assert_eq!(b.params[P_REDUCTION].load(Ordering::Relaxed), 21.0);
    assert_eq!(b.saved_profile.lock().as_ref().map(|p| p.bins.clone()), Some(bins.clone()));
    assert_eq!(b.incoming_profile.lock().as_ref().map(|p| p.bins.clone()), Some(bins));
    // No profile: the field is omitted and loading stays adaptive.
    let c = PluginShared::new();
    let plain = c.save_state_json();
    assert!(!plain.contains("profile"));
    PluginShared::new().load_state_json(&plain).expect("plain state loads");
}

/// States written before the shared `SimpleState::capture`/`restore_params` helpers, verbatim:
/// one with the profile, one from the oldest SDK format (no preset, no key), and a foreign
/// version that must be refused rather than half-applied.
#[test]
fn states_written_by_earlier_builds_still_load() {
    use std::sync::atomic::Ordering;
    let with_profile = r#"{"version":1,"params":[0.0,21.0,6.0,50.0,50.0,0.8,0.0,-3.0,70.0],"bypass":true,"active_preset":2,"key_track":"Vox","profile":{"sample_rate":48000.0,"bins":[[1.0,2.0],[3.0,4.0]]}}"#;
    let s = superduper_denoise::PluginShared::new();
    s.load_state_json(with_profile).expect("load");
    assert_eq!(s.params[superduper_denoise::P_REDUCTION].load(Ordering::Relaxed), 21.0);
    assert_eq!(s.params[superduper_denoise::P_MIX].load(Ordering::Relaxed), 70.0);
    assert!(s.bypass.load(Ordering::Relaxed));
    assert_eq!(s.active_preset.load(Ordering::Relaxed), 2);
    assert_eq!(*s.scope.key_track.lock(), "Vox");
    assert_eq!(s.saved_profile.lock().as_ref().map(|p| p.bins.clone()), Some(vec![vec![1.0, 2.0], vec![3.0, 4.0]]));

    let oldest = r#"{"version":1,"params":[1.0,12.0],"bypass":false}"#;
    let o = superduper_denoise::PluginShared::new();
    o.load_state_json(oldest).expect("oldest format loads");
    assert_eq!(o.params[superduper_denoise::P_MODE].load(Ordering::Relaxed), 1.0);
    assert_eq!(o.params[superduper_denoise::P_MIX].load(Ordering::Relaxed), 100.0, "missing params keep their value");
    assert!(o.saved_profile.lock().is_none());

    let foreign = r#"{"version":2,"params":[2.0],"bypass":false}"#;
    let f = superduper_denoise::PluginShared::new();
    assert_eq!(f.load_state_json(foreign), Err("state version mismatch"));
    assert_eq!(f.params[superduper_denoise::P_MODE].load(Ordering::Relaxed), 0.0, "refused state changes nothing");
}

/// Render with Mode = Neural and the given Mix, every other param at its default.
fn render_neural(x: &[f32], mix: f64) -> (Vec<f32>, Vec<f32>) {
    use clack_common::events::{event_types::ParamValueEvent, Pckn};
    use clack_common::utils::{ClapId, Cookie};
    let mode = ClapId::new(superduper_denoise::P_MODE as u32);
    let mix_id = ClapId::new(superduper_denoise::P_MIX as u32);
    sdsp_test_kit::host::render_with::<Target>(SR, 512, x, x, move |pos, buf| {
        if pos == 0 {
            buf.push(&ParamValueEvent::new(0, mode, Pckn::match_all(), 2.0, Cookie::empty()));
            buf.push(&ParamValueEvent::new(0, mix_id, Pckn::match_all(), mix, Cookie::empty()));
        }
    })
}

/// The voiced test talker the restore tests use: harmonic stack on a gliding f0 with formant
/// bumps, 4 Hz syllables with silent gaps.
#[path = "../../../restore/tests/common/mod.rs"]
mod common;
use common::voiced;

/// Neural through the real CLAP host at 48 kHz: noise between syllables is removed, Mix 50 lands
/// in between, and process() stays allocation-free with the network and the mix path running.
/// Noise alone is the wrong probe for RNNoise: offline, white noise with no voice in it was cut
/// anywhere from −1 to −46 dB depending only on the noise seed. With a voice present the result
/// is stable (SNR +4 / +9 / +10.5 dB at noise 0.01 / 0.03 / 0.06, six seeds each).
#[test]
fn neural_through_the_plugin_cleans_gaps_without_allocating() {
    let frames = SR as usize * 4;
    let s = voiced(frames);
    let x: Vec<f32> = s.iter().zip(probes::noise(frames, 0.03)).map(|(a, b)| a + b).collect();
    // The host gets the output 2048 samples late (the reported latency), so compare shifted.
    const LAT: usize = 2048;
    let gaps: Vec<usize> = (SR as usize..frames - LAT).filter(|&i| s[i].abs() < 1e-6).collect();
    let gap_db = |y: &[f32]| {
        let wet: f64 = gaps.iter().map(|&i| (y[i + LAT] as f64).powi(2)).sum();
        let dry: f64 = gaps.iter().map(|&i| (x[i] as f64).powi(2)).sum();
        10.0 * (wet / dry).log10()
    };
    let (full, _) = render_neural(&x, 100.0);
    let (half, _) = render_neural(&x, 50.0);
    let (cut, cut_half) = (gap_db(&full), gap_db(&half));
    eprintln!("neural through the plugin: noise in gaps {cut:.1} dB at mix 100, {cut_half:.1} dB at mix 50");
    assert!(cut < -12.0, "neural only cut {cut:.1} dB between syllables");
    assert!(cut_half > cut + 3.0 && cut_half < -3.0, "mix 50 should land between: {cut_half:.1} dB");
    sdsp_test_kit::alloc::reset();
    let _ = render_neural(&probes::noise(1 << 14, 0.3), 70.0);
    sdsp_test_kit::alloc::assert_rt_clean("superduper-denoise neural", (1 << 14) / 512);
}
